{"implementation":"import math


def solve(case):
    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case must contain threshold and calls")

    threshold = case["threshold"]
    calls = case["calls"]
    if not is_number(threshold) or not math.isfinite(threshold):
        raise ValueError("threshold must be a finite number")
    if threshold < 0:
        raise ValueError("threshold must be non-negative")
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )
    validated = []
    seen_ids = set()

    for call in calls:
        if not isinstance(call, dict) or any(field not in call for field in required):
            raise ValueError("each call must contain every required field")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        if call_id in seen_ids:
            raise ValueError("call_id values must be unique")
        seen_ids.add(call_id)
        if not is_number(loss_without) or not math.isfinite(loss_without) or loss_without < 0:
            raise ValueError("loss_without_call must be a finite non-negative number")
        if not is_number(loss_with) or not math.isfinite(loss_with) or loss_with < 0:
            raise ValueError("loss_with_call must be a finite non-negative number")
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int) or prediction_tokens < 0:
            raise ValueError("prediction_tokens must be a non-negative integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        validated.append((call_id, float(loss_without), float(loss_with), prediction_tokens, parseable))

    diagnostics = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        normalized_gain = (loss_without - loss_with) / max(1, prediction_tokens)
        accepted = parseable and normalized_gain >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 8),
        })

    accepted_call_ids = [item["call_id"] for item in diagnostics if item["accepted"]]
    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics,
    }
